SELECT dataTable.warning_type_id typeId,dataTable.warning_type_name as 'typeName',
date_format(dataTable.create_date,'%Y-%m-%d') 'createDate',SUM(dataTable.warning_num) num
FROM vm_statistics_event_type dataTable

AND dataTable.create_date >= #{queryStartTime}
AND dataTable.create_date <= #{queryEndTime}

    AND dataTable.warning_type_id IN

        #{labelIdItem}



    AND (dataTable.county_id = #{countyId} or dataTable.province_id = #{countyId} or dataTable.city_id = #{countyId})

    ${dataScope}

GROUP BY dataTable.warning_type_id,date_format(dataTable.create_date,'%Y-%m-%d')

    UNION
    SELECT 'aaa666' typeId,'其他' typeName,date_format(dataTable.create_date,'%Y-%m-%d') createDate,SUM(dataTable.warning_num) num
    FROM vm_statistics_event_type dataTable

    AND dataTable.create_date >= #{queryStartTime}
    AND dataTable.create_date <= #{queryEndTime}

        AND dataTable.warning_type_id NOT IN

            #{labelIdItem}



        AND (dataTable.county_id = #{countyId} or dataTable.province_id = #{countyId} or dataTable.city_id = #{countyId})

        ${dataScope}

    GROUP BY date_format(dataTable.create_date,'%Y-%m-%d')

SELECT dataTable.warning_type_id tagId,
date_format(dataTable.create_date,'%Y-%m-%d') createDate,SUM(dataTable.warning_num) num
FROM vm_statistics_event_tag dataTable

AND dataTable.create_date >= #{queryStartTime}
AND dataTable.create_date <= #{queryEndTime}

    AND dataTable.warning_type_id IN

        #{labelIdItem}



    AND (dataTable.county_id = #{countyId} or dataTable.province_id = #{countyId} or dataTable.city_id = #{countyId})

    ${dataScope}

GROUP BY dataTable.warning_type_id,date_format(dataTable.create_date,'%Y-%m-%d')

    UNION
    SELECT 'aaa666' tagId, date_format(dataTable.create_date,'%Y-%m-%d') createDate,SUM(dataTable.warning_num) num
    FROM vm_statistics_event_tag dataTable

    AND dataTable.create_date >= #{queryStartTime}
    AND dataTable.create_date <= #{queryEndTime}

        AND dataTable.warning_type_id NOT IN

            #{labelIdItem}



        AND (dataTable.county_id = #{countyId} or dataTable.province_id = #{countyId} or dataTable.city_id = #{countyId})

        ${dataScope}

    GROUP BY date_format(dataTable.create_date,'%Y-%m-%d')

SELECT IFNULL(SUM(dataTable.yesterday_all),0) AS 'yesterdayAll'
FROM vm_statistics_event_num_yesterday dataTable


        AND DATE_FORMAT(dataTable.create_date,'%Y-%m-%d') = DATE_FORMAT(NOW() ,'%Y-%m-%d')


        AND dataTable.create_date >= #{queryStartTime}
        AND dataTable.create_date <= #{queryEndTime}


        AND LEFT(dataTable.county_id,2) = LEFT(#{provinceId},2)


        AND LEFT(dataTable.county_id,4) = LEFT(#{cityId},4)


        AND (dataTable.county_id = #{countyId} or dataTable.province_id = #{countyId} or dataTable.city_id = #{countyId})

    ${dataScope}

SELECT SUM(dataTable.less_one) AS 'lessOneHour',SUM(dataTable.one_five) AS 'oneFiveHour',
SUM(dataTable.five_ten) AS 'fiveTenHour',SUM(dataTable.more_ten) AS 'overTenHour'
FROM vm_statistics_event_duration dataTable


    AND LEFT(dataTable.county_id,2) = LEFT(#{provinceId},2)


    AND LEFT(dataTable.county_id,4) = LEFT(#{cityId},4)


    AND (dataTable.county_id = #{countyId} or dataTable.province_id = #{countyId} or dataTable.city_id = #{countyId})


    AND dataTable.create_date >= #{queryStartTime}
    AND dataTable.create_date <= #{queryEndTime}

    ${dataScope}

SELECT region_name AS 'regionName', round(sum(handle_duration)/3600/sum(duration_num),2) AS 'avgTime', province_id AS 'provinceId', city_id AS 'cityId', county_id AS 'countyId' FROM vm_statistics_event_handle dataTable
AND create_date >= #{queryStartTime} AND create_date <= #{queryEndTime}
AND province_id = #{provinceId}
AND city_id = #{cityId}
AND (dataTable.county_id = #{countyId} or dataTable.province_id = #{countyId} or dataTable.city_id = #{countyId})
${dataScope}
GROUP BY province_id, city_id, county_id order by avgTime desc
